traps.Trap05.txt:
	If ($Event <> 210) @end;
	PlayerGoto(10, 43);
	SetPlayerDir(0);
	SetPlayerScn();
	MoveScreen(6, 40, 2);
	Say("宋四郎：说起这<color=Red>霹雳堂<color=Black>的防卫也称得上是天罗地网了！");
	Say("汪信之：当然了！霹雳堂到处杀人放火，欺男霸女，他们也怕人家来报仇啊！不防备森严一点，给人家找上门来，那不就麻烦了吗！");
	Say("宋四郎：听说前些日子青蛟帮和霹雳堂的人结下梁子，青蛟帮一大群人大白天闯进霹雳堂，被霹雳堂手下杀个片甲不留。特别是霹雳堂<color=Red>堂主尚进<color=Black>，据说用一个叫什么<color=Red>雷震子<color=Black><enter>的宝物发射了一个火器，把青蛟帮帮主炸得粉身碎骨，连尸体都找不到了。");
	Say("汪信之：这么说霹雳堂堪比铜墙铁壁啊！");
	Say("宋四郎：不错，我师父说霹雳堂戒备森严，高手如云，要我千万不能惹上霹雳堂的人。");
	Say("汪信之：确实应该如此，还是少惹事的好！");
	MoveScreen(2, 40, 2);
	Say("杨影枫：看来霹雳堂白天是不容易进去的了，我还是还是先找个地方歇歇，等挨到<color=Red>天黑<color=Black>再想办法吧！最好能神不知鬼不觉地偷出来，也可免了不必要的麻烦。", 2);
	Assign($Event, 211);
	AddToMemo(90330);
	SetMapTrap(5, "");
	SetMapTrap(1, "Trap01.txt");
	Return;
@end:
	Return;

